//! Field transfer decisions from the same Rust table used by coverage tests (#3311).
use raw_core::types::{
    transfer_mode, AdjustmentGroup, AdjustmentModel, TransferMode, WbScaleVersion,
    ADJUSTMENT_SCHEMA, NON_COPYABLE_FIELDS, TRANSFER_XMP_ATTRIBUTES, TRANSFER_XMP_ELEMENTS,
};

fn fields() -> impl Iterator<Item = &'static str> {
    AdjustmentGroup::ALL
        .iter()
        .flat_map(|g| g.fields().iter().copied())
        .chain(NON_COPYABLE_FIELDS.iter().copied())
}

pub fn emit_ts() -> String {
    let mut out = String::from(
        "// Generated by tools/codegen.sh from schema/groups/transfer.rs. DO NOT EDIT.\n\n\
export type AdjustmentTransferMode = 'Absolute' | 'Relative' | 'AssetRelative' | 'Unsupported';\n\n\
/** Relative fields also support an explicit camera As Shot correction. */\n\
export const ADJUSTMENT_TRANSFER_MODES: Readonly<Record<string, AdjustmentTransferMode>> = {\n",
    );
    for field in fields() {
        out.push_str(&format!(
            "  {field}: '{}',\n",
            transfer_mode(field).expect("transfer decision").name()
        ));
    }
    out.push_str("};\n");
    let scale = match AdjustmentModel::default().wb_scale_version {
        WbScaleVersion::V1 => 1,
        WbScaleVersion::V2 => 2,
        WbScaleVersion::V3 => 3,
        WbScaleVersion::V4 => 4,
        WbScaleVersion::V5 => 5,
    };
    out.push_str(&format!(
        "\nexport const CURRENT_WHITE_BALANCE_SCALE_VERSION = {scale};\n"
    ));
    out.push_str("\nexport const RELATIVE_TRANSFER_RANGES: Readonly<Record<string, readonly [number, number]>> = {\n");
    for field in ADJUSTMENT_SCHEMA
        .iter()
        .filter(|field| transfer_mode(field.name) == Some(TransferMode::Relative))
    {
        out.push_str(&format!(
            "  {}: [{}, {}],\n",
            field.name, field.range.0, field.range.1
        ));
    }
    out.push_str("};\n");
    out.push_str(
        "\nexport const TRANSFER_XMP_ATTRIBUTES: Readonly<Record<string, readonly string[]>> = {\n",
    );
    for (field, attributes) in TRANSFER_XMP_ATTRIBUTES {
        let values = attributes
            .iter()
            .map(|key| format!("'{key}'"))
            .collect::<Vec<_>>();
        let row = format!("  {field}: [{}],\n", values.join(", "));
        if row.len() <= 101 {
            out.push_str(&row);
        } else {
            out.push_str(&format!(
                "  {field}: [\n{}  ],\n",
                values
                    .iter()
                    .map(|value| format!("    {value},\n"))
                    .collect::<String>()
            ));
        }
    }
    out.push_str(
        "};\n\nexport const TRANSFER_XMP_ELEMENTS: Readonly<Record<string, string>> = {\n",
    );
    for (field, key) in TRANSFER_XMP_ELEMENTS {
        out.push_str(&format!("  {field}: '{key}',\n"));
    }
    out.push_str("};\n");
    out
}

pub fn emit_swift() -> String {
    let mut out = String::from(
        "// Generated by tools/codegen.sh from schema/groups/transfer.rs. DO NOT EDIT.\n\n\
public enum AdjustmentTransferMode: String, Sendable {\n\
\x20 case absolute = \"Absolute\"\n\
\x20 case relative = \"Relative\"\n\
\x20 case assetRelative = \"AssetRelative\"\n\
\x20 case unsupported = \"Unsupported\"\n\
}\n\n\
/// Relative fields also support an explicit camera As Shot correction.\n\
public let adjustmentTransferModes: [String: AdjustmentTransferMode] = [\n",
    );
    for field in fields() {
        let name = transfer_mode(field).expect("transfer decision").name();
        let lower = format!("{}{}", name[..1].to_lowercase(), &name[1..]);
        out.push_str(&format!("  \"{field}\": .{lower},\n"));
    }
    out.push_str("]\n");
    out
}

fn kotlin_strings(values: &[&str]) -> String {
    values
        .iter()
        .map(|value| format!("\"{value}\""))
        .collect::<Vec<_>>()
        .join(", ")
}

/// Android reads the same decisions, wire keys and group membership.
pub fn emit_kotlin() -> String {
    let mut out = String::from(
        "// Generated by tools/codegen.sh from schema/groups/transfer.rs. DO NOT EDIT.\n\
package app.justmaple.aperture.generated\n\n\
enum class AdjustmentTransferMode { Absolute, Relative, AssetRelative, Unsupported }\n\n\
data class AdjustmentTransferGroup(val id: String, val label: String, val fields: List<String>)\n\n\
object AdjustmentTransfer {\n\
\x20   /** Relative fields also support an explicit camera As Shot correction. */\n\
\x20   val modes: Map<String, AdjustmentTransferMode> = mapOf(\n",
    );
    for field in fields() {
        let mode = transfer_mode(field).expect("transfer decision").name();
        out.push_str(&format!(
            "        \"{field}\" to AdjustmentTransferMode.{mode},\n"
        ));
    }
    out.push_str("    )\n\n    val xmpAttributes: Map<String, List<String>> = mapOf(\n");
    for (field, attributes) in TRANSFER_XMP_ATTRIBUTES {
        out.push_str(&format!(
            "        \"{field}\" to listOf({}),\n",
            kotlin_strings(attributes)
        ));
    }
    out.push_str("    )\n\n    val xmpElements: Map<String, String> = mapOf(\n");
    for (field, key) in TRANSFER_XMP_ELEMENTS {
        out.push_str(&format!("        \"{field}\" to \"{key}\",\n"));
    }
    out.push_str("    )\n\n    /** Presentation order of the paste picker. */\n    val groups: List<AdjustmentTransferGroup> = listOf(\n");
    for group in AdjustmentGroup::ALL {
        out.push_str(&kotlin_group(*group));
    }
    out.push_str("    )\n}\n");
    out
}

fn kotlin_group(group: AdjustmentGroup) -> String {
    let members = group
        .fields()
        .iter()
        .map(|field| format!("                \"{field}\",\n"))
        .collect::<String>();
    format!(
        "        AdjustmentTransferGroup(\n            \"{}\",\n            \"{}\",\n            listOf(\n{members}            ),\n        ),\n",
        group.id(),
        group.label(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn decisions_are_generated_for_every_consumer() {
        let kotlin = emit_kotlin();
        for field in fields() {
            let mode = transfer_mode(field).unwrap().name();
            assert!(emit_ts().contains(&format!("{field}: '{mode}'")));
            assert!(emit_swift().contains(&format!("\"{field}\": .")));
            assert!(kotlin.contains(&format!("\"{field}\" to AdjustmentTransferMode.{mode},")));
        }
        for (field, attributes) in TRANSFER_XMP_ATTRIBUTES {
            let row = format!("\"{field}\" to listOf({}),", kotlin_strings(attributes));
            assert!(kotlin.contains(&row), "{row}");
        }
        for (field, key) in TRANSFER_XMP_ELEMENTS {
            assert!(kotlin.contains(&format!("\"{field}\" to \"{key}\",")));
        }
        for group in AdjustmentGroup::ALL {
            let block = kotlin_group(*group);
            assert!(kotlin.contains(&block));
            assert!(block.contains(&format!("\"{}\",\n", group.label())));
            for field in group.fields() {
                assert!(block.contains(&format!("\"{field}\",\n")));
            }
        }
        assert!(emit_ts().contains("crop: 'AssetRelative'"));
        assert!(emit_ts().contains("inpaint_removals: 'Unsupported'"));
        assert_eq!(emit_ts(), emit_ts());
        assert_eq!(emit_swift(), emit_swift());
        assert_eq!(kotlin, emit_kotlin());
    }
}
